+
+			c, err := NewContainerLab(
+				WithTimeout(time.Minute),
+				WithTopoPath(writeTopo(t, mgmtNetLinkAutoBridgeTopo), nil),
+				WithRuntime("mgmtresolvetest", &clabruntime.RuntimeConfig{}),
+				WithSkippedBindsPathsCheck(),
