package links

import (
	"context"
	"fmt"
	"slices"
	"sync"

	"github.com/charmbracelet/log"
	"github.com/containernetworking/plugins/pkg/ns"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabutils "github.com/srl-labs/containerlab/utils"
	"github.com/vishvananda/netlink"
)

type LinkMgmtNetRaw struct {
	LinkCommonParams `             yaml:",inline"`
	HostInterface    string       `yaml:"host-interface"`
	Endpoint         *EndpointRaw `yaml:"endpoint"`
	// Network is the name of the management network the link attaches to.
	// An empty value selects the default (first) management network.
	Network string `yaml:"network,omitempty"`
}

func (r *LinkMgmtNetRaw) ToLinkBriefRaw() *LinkBriefRaw {
	lc := &LinkBriefRaw{
		Endpoints: make([]string, 2),
		LinkCommonParams: LinkCommonParams{
			MTU:    r.MTU,
			Labels: r.Labels,
			Vars:   r.Vars,
		},
	}

	lc.Endpoints[0] = fmt.Sprintf("%s:%s", r.Endpoint.Node, r.Endpoint.Iface)
	lc.Endpoints[1] = fmt.Sprintf("%s:%s", "mgmt-net", r.HostInterface)

	return lc
}

func (r *LinkMgmtNetRaw) Resolve(params *ResolveParams) (Link, error) {
	// filtered true means the link is in the filter provided by a user
	// aka it should be resolved/created/deployed
	filtered := isInFilter(params, []*EndpointRaw{r.Endpoint})
	if !filtered {
		return nil, nil
	}

	// create the LinkMgmtNet struct
	link := &LinkVEth{
		LinkCommonParams: r.LinkCommonParams,
	}

	// Normalize link vars to ensure JSON serialization compatibility
	link.Vars = normalizeVars(link.Vars)

	network := r.Network
	if network == params.DefaultMgmtNetwork {
		network = ""
	}
	mgmtBridgeNode := getMgmtBrLinkNode(network)
	if mgmtBridgeNode == nil {
		return nil, fmt.Errorf("failed to get the mgmt-net link node for network %q", r.Network)
	}

	bridgeEp := NewEndpointBridge(NewEndpointGeneric(mgmtBridgeNode, r.HostInterface, link), true)

	var err error
	bridgeEp.MAC, err = clabutils.GenMac(clabconstants.ClabOUI)
	if err != nil {
		return nil, err
	}

	// resolve and populate the endpoint
	contEp, err := r.Endpoint.Resolve(params, link)
	if err != nil {
		return nil, err
	}

	link.Endpoints = []Endpoint{bridgeEp, contEp}

	// add link to respective endpoint nodes
	_ = bridgeEp.GetNode().AddEndpoint(bridgeEp)

	// set default link mtu if MTU is unset
	if link.MTU == 0 {
		link.MTU = clabconstants.DefaultLinkMTU
	}

	return link, nil
}

func (*LinkMgmtNetRaw) GetType() LinkType {
	return LinkTypeMgmtNet
}

func mgmtNetLinkFromBrief(lb *LinkBriefRaw, specialEPIndex int) (*LinkMgmtNetRaw, error) {
	_, hostIf, node, nodeIf, err := extractHostNodeInterfaceData(lb, specialEPIndex)
	if err != nil {
		return nil, err
	}

	link := &LinkMgmtNetRaw{
		LinkCommonParams: lb.LinkCommonParams,
		HostInterface:    hostIf,
		Endpoint:         NewEndpointRaw(node, nodeIf, ""),
	}

	// set default link mtu if MTU is unset
	if link.MTU == 0 {
		link.MTU = clabconstants.DefaultLinkMTU
	}

	return link, nil
}

// mgmtNetOwnerName is the logical owner name of the interfaces created for
// mgmt-net links, shared by the mgmt-net link nodes of all management networks.
const mgmtNetOwnerName = "mgmt-net"

var (
	// _mgmtBrLinkNodes holds the mgmt-net link nodes keyed by the management
	// network name. The empty name is the default management network.
	_mgmtBrLinkNodes   = map[string]*mgmtBridgeLinkNode{}
	_mgmtBrLinkNodesMu sync.Mutex
)

// mgmtBridgeLinkNode is a special node that represents the mgmt bridge node
// that is used when mgmt-net link is defined in the topology.
type mgmtBridgeLinkNode struct {
	GenericLinkNode
}

func (*mgmtBridgeLinkNode) GetLinkEndpointType() LinkEndpointType {
	return LinkEndpointTypeBridge
}

func (b *mgmtBridgeLinkNode) AddLinkToContainer(
	_ context.Context,
	link netlink.Link,
	f func(ns.NetNS) error,
) error {
	// retrieve the namespace handle
	curNamespace, err := ns.GetCurrentNS()
	if err != nil {
		return err
	}

	// get the bridge as netlink.Link
	br, err := netlink.LinkByName(b.shortname)
	if err != nil {
		return err
	}

	// assign the bridge to the link as master
	err = netlink.LinkSetMaster(link, br)
	if err != nil {
		return err
	}

	// execute the given function
	return curNamespace.Do(f)
}

// getMgmtBrLinkNode returns the mgmt-net link node of the given management network,
// creating it on first use. The empty network name selects the default network.
func getMgmtBrLinkNode(network string) *mgmtBridgeLinkNode {
	_mgmtBrLinkNodesMu.Lock()
	defer _mgmtBrLinkNodesMu.Unlock()

	if n, ok := _mgmtBrLinkNodes[network]; ok {
		return n
	}

	currns, err := ns.GetCurrentNS()
	if err != nil {
		log.Errorf("failed to get current network namespace: %v", err)
		return nil
	}
	n := &mgmtBridgeLinkNode{
		GenericLinkNode: GenericLinkNode{
			shortname: mgmtNetOwnerName,
			endpoints: []Endpoint{},
			nspath:    currns.Path(),
		},
	}
	_mgmtBrLinkNodes[network] = n

	return n
}

// IsUnresolvedMgmtBridgeEndpoint reports whether ep is a mgmt-net endpoint whose
// management network bridge is not known yet, e.g. because the network is not created.
func IsUnresolvedMgmtBridgeEndpoint(ep Endpoint) bool {
	if !ep.IsNodeless() || ep.GetNode().GetLinkEndpointType() != LinkEndpointTypeBridge {
		return false
	}
	bridge := ep.GetNode().GetShortName()
	return bridge == "" || bridge == mgmtNetOwnerName
}

// GetMgmtBrLinkNode returns the mgmt-net link node of the default management network.
func GetMgmtBrLinkNode() Node { // skipcq: RVV-B0001
	return getMgmtBrLinkNode("")
}

// GetMgmtBrLinkNodes returns the mgmt-net link nodes of all management networks
// that have been referenced so far, starting with the default network.
func GetMgmtBrLinkNodes() []Node {
	var nodes []Node
	if n := getMgmtBrLinkNode(""); n != nil {
		nodes = append(nodes, n)
	}

	_mgmtBrLinkNodesMu.Lock()
	defer _mgmtBrLinkNodesMu.Unlock()

	networks := make([]string, 0, len(_mgmtBrLinkNodes))
	for network := range _mgmtBrLinkNodes {
		if network != "" {
			networks = append(networks, network)
		}
	}
	slices.Sort(networks)

	for _, network := range networks {
		nodes = append(nodes, _mgmtBrLinkNodes[network])
	}

	return nodes
}

// SetMgmtNetUnderlyingBridge sets the bridge of the default management network.
func SetMgmtNetUnderlyingBridge(bridge string) error {
	return SetMgmtNetworkUnderlyingBridge("", bridge)
}

// SetMgmtNetworkUnderlyingBridge sets the bridge the mgmt-net links of the given
// management network attach to. The empty network name selects the default network.
func SetMgmtNetworkUnderlyingBridge(network, bridge string) error {
	n := getMgmtBrLinkNode(network)
	if n == nil {
		return fmt.Errorf("failed to get the mgmt-net link node for network %q", network)
	}
	n.GenericLinkNode.shortname = bridge
	return nil
}

package core

import (
	"context"
	"fmt"
	"net/netip"
	"slices"

	"github.com/charmbracelet/log"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clablinks "github.com/srl-labs/containerlab/links"
	"github.com/srl-labs/containerlab/mgmt"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabtypes "github.com/srl-labs/containerlab/types"
)

func (c *CLab) CreateNetwork(ctx context.Context) error {
	defined := c.allMgmtNetworks()
	networks := make(clabtypes.MgmtNetworks, 0, len(defined))
	for _, m := range defined {
		if c.skipMgmtNetwork(m) {
			log.Debug("Skipping management network, no node uses it", "network", m.Network)
			continue
		}
		networks = append(networks, m)
	}
	return c.createNetworks(ctx, networks)
}

// createNetworks creates or inspects the given management networks
// and labels the nodes with their management bridge.
func (c *CLab) createNetworks(ctx context.Context, networks clabtypes.MgmtNetworks) error {
	for _, m := range networks {
		var opts []clabruntime.NetworkCreateOptions
		if addresses := c.staticManagementAddresses(m); len(addresses) != 0 {
			opts = append(opts, clabruntime.NetworkCreateOptions{StaticAddresses: addresses})
		}

		rt, err := c.mgmtRuntime(c.globalRuntimeName, m)
		if err != nil {
			return err
		}
		// create docker network or use existing one
		if err := rt.CreateNet(ctx, opts...); err != nil {
			return err
		}

		// VM kinds read the subnets at init, before the runtime resolved them
		for _, cfg := range c.mgmtNetNodes(m) {
			for key, subnet := range map[string]string{
				"DOCKER_NET_V4_ADDR": m.IPv4Subnet,
				"DOCKER_NET_V6_ADDR": m.IPv6Subnet,
			} {
				if value, ok := cfg.Env[key]; ok && value == "" {
					cfg.Env[key] = subnet
				}
			}
		}
	}

	// save mgmt bridge name as a label
	for _, n := range c.Nodes {
		bridge := c.globalRuntime().Mgmt().Bridge
		if m := c.mgmtNetByNetwork(n.Config().MgmtNet); m != c.Config.Mgmt {
			bridge = m.Bridge
		}
		n.Config().Labels[clabconstants.NodeMgmtNetBr] = bridge
	}

	return nil
}

// mgmtNetNodes returns the configs of the nodes attached to the given management network.
func (c *CLab) mgmtNetNodes(m *clabtypes.MgmtNet) []*clabtypes.NodeConfig {
	var configs []*clabtypes.NodeConfig
	for _, node := range c.Nodes {
		if c.mgmtNetByNetwork(node.Config().MgmtNet) == m {
			configs = append(configs, node.Config())
		}
	}
	return configs
}

// SyncMgmtHostRoutes reconciles host routes to current macvlan management endpoints.
func (c *CLab) SyncMgmtHostRoutes(ctx context.Context) error {
	if c.Config == nil || c.Config.Mgmt == nil {
		return nil
	}
	c.mgmtRouteMu.Lock()
	defer c.mgmtRouteMu.Unlock()
	for _, m := range c.allMgmtNetworks() {
		if m.Driver != clabtypes.MgmtDriverMacvlan || !m.MacvlanAuxEnabled() {
			continue
		}
		rt, err := c.mgmtRuntime(c.globalRuntimeName, m)
		if err != nil {
			return err
		}
		if err := rt.SyncMgmtHostRoutes(ctx); err != nil {
			return err
		}
	}
	return nil
}

func (c *CLab) staticManagementAddresses(m *clabtypes.MgmtNet) []netip.Addr {
	var addresses []netip.Addr
	for _, config := range c.mgmtNetNodes(m) {
		if address, err := netip.ParseAddr(config.MgmtIPv4Address); err == nil {
			addresses = append(addresses, address)
		}
		if address, err := netip.ParseAddr(config.MgmtIPv6Address); err == nil {
			addresses = append(addresses, address)
		}
	}
	return addresses
}

// validateManagementLinks checks that every mgmt-net link references a defined
// management network that is backed by a bridge.
func (c *CLab) validateManagementLinks() error {
	if c.Config.Topology == nil {
		return nil
	}
	for _, link := range c.Config.Topology.Links {
		if link == nil || link.Link == nil {
			continue
		}
		mgmtNetLink, ok := link.Link.(*clablinks.LinkMgmtNetRaw)
		if !ok {
			continue
		}
		m, err := c.mgmtNetByName(mgmtNetLink.Network)
		if err != nil {
			return fmt.Errorf("mgmt-net link: %w", err)
		}
		if m.Driver == clabtypes.MgmtDriverMacvlan {
			if mgmtNetLink.Network == "" {
				return fmt.Errorf(
					"mgmt-net links require a bridge management network and cannot be used with mgmt.driver %q",
					m.Driver,
				)
			}
			return fmt.Errorf(
				"mgmt-net links require a bridge management network and cannot use management network %q with driver %q",
				m.Network,
				m.Driver,
			)
		}
	}
	return nil
}

// mgmtNetLinkNetworks returns the management networks referenced by mgmt-net links.
func (c *CLab) mgmtNetLinkNetworks() []*clabtypes.MgmtNet {
	if c.Config.Topology == nil {
		return nil
	}
	var networks []*clabtypes.MgmtNet
	for _, link := range c.Config.Topology.Links {
		if link == nil || link.Link == nil {
			continue
		}
		mgmtNetLink, ok := link.Link.(*clablinks.LinkMgmtNetRaw)
		if !ok {
			continue
		}
		if m, err := c.mgmtNetByName(mgmtNetLink.Network); err == nil {
			networks = append(networks, m)
		}
	}
	return networks
}

// resolveMgmtNetLinkNetworks populates the bridge names of the non-default management
// networks that mgmt-net links reference without an explicit bridge. The runtime names
// such a bridge when it creates the network, so the bridge of an existing network is
// looked up from the runtime. The lookup neither creates networks nor changes host
// state, so it is safe for dry runs. Networks that do not exist yet are left unresolved
// until they are created.
func (c *CLab) resolveMgmtNetLinkNetworks(ctx context.Context) error {
	var resolved clabtypes.MgmtNetworks
	for _, m := range c.mgmtNetLinkNetworks() {
		if m == c.Config.Mgmt || m.Bridge != "" || slices.Contains(resolved, m) {
			continue
		}
		resolved = append(resolved, m)

		rt, err := c.mgmtRuntime(c.globalRuntimeName, m)
		if err != nil {
			return fmt.Errorf("mgmt-net link selects network %q: %w", m.Network, err)
		}
		resolver, ok := rt.(clabruntime.MgmtBridgeResolver)
		if !ok {
			continue
		}
		if err := resolver.ResolveMgmtBridge(ctx); err != nil {
			return err
		}
	}
	return nil
}

// setMgmtNetLinkBridges points the mgmt-net link nodes of the management networks
// that mgmt-net links select at the bridge of that network.
func (c *CLab) setMgmtNetLinkBridges() error {
	if err := clablinks.SetMgmtNetUnderlyingBridge(c.Config.Mgmt.Bridge); err != nil {
		return err
	}
	for _, m := range c.mgmtNetLinkNetworks() {
		if m == c.Config.Mgmt || m.Network == "" {
			continue
		}
		if err := clablinks.SetMgmtNetworkUnderlyingBridge(m.Network, m.Bridge); err != nil {
			return err
		}
	}
	return nil
}

// AllocateToolManagementIPs assigns addresses when the topology uses containerlab IPAM.
func (c *CLab) AllocateToolManagementIPs(ctx context.Context, cfg *clabtypes.NodeConfig) error {
	m := c.mgmtNetByNetwork(cfg.MgmtNet)
	if m.IPAM.Provider == clabtypes.IPAMProviderRuntime {
		return nil
	}
	// tools attach to a network on demand, so it is created even when it is
	// flagged as skipped-when-unused by the topology
	if err := c.createNetworks(ctx, clabtypes.MgmtNetworks{m}); err != nil {
		return err
	}
	reserved, err := c.collectReservedManagementAddresses(ctx, m, nil)
	if err != nil {
		return err
	}
	return mgmt.AllocateManagementIPs(
		ctx,
		m,
		[]*clabtypes.NodeConfig{cfg},
		clabtypes.AllocationOptions{Reserved: reserved},
	)
}

// skipMgmtNetwork reports whether the management network m must not be created
// because it is not used: skip-when-unused is set on it and no node attached to
// it resolves to a network mode that attaches to the management network.
func (c *CLab) skipMgmtNetwork(m *clabtypes.MgmtNet) bool {
	if m == nil || !m.SkipWhenUnused {
		return false
	}

	topo := c.Config.Topology
	if topo == nil || len(topo.Nodes) == 0 {
		return false
	}

	// a network that mgmt-net links attach to is in use
	if slices.Contains(c.mgmtNetLinkNetworks(), m) {
		return false
	}

	for name := range topo.Nodes {
		if topo.GetNodeNetworkMode(name) == "none" {
			continue
		}
		if c.mgmtNetByNetwork(topo.GetNodeMgmtNet(name)) == m {
			return false
		}
	}

	return true
}

// mgmtNetworksSkipped reports whether every defined management network is
// skipped because it is unused.
func (c *CLab) mgmtNetworksSkipped() bool {
	for _, m := range c.allMgmtNetworks() {
		if !c.skipMgmtNetwork(m) {
			return false
		}
	}
	return true
}

package core

import (
	"context"
	"fmt"
	"net/netip"

	clabtypes "github.com/srl-labs/containerlab/types"

	clablinks "github.com/srl-labs/containerlab/links"
)

// ApplyResult summarizes the changes applied by an apply operation.
type ApplyResult struct {
	DryRun           bool     `json:"dry-run"`
	DeployedLab      bool     `json:"deployed-lab"`
	LabName          string   `json:"lab-name,omitempty"`
	AddedNodes       []string `json:"added-nodes"`
	DeletedNodes     []string `json:"deleted-nodes"`
	RecreatedNodes   []string `json:"recreated-nodes"`
	StartedNodes     []string `json:"started-nodes"`
	AddedLinks       []string `json:"added-links"`
	DeletedEndpoints []string `json:"deleted-endpoints"`
	RestartedNodes   []string `json:"restarted-nodes"`
	// NodeChangeReasons explains per node why apply restarts or recreates it,
	// e.g. "added link" or "config drift: image".
	NodeChangeReasons map[string]string `json:"node-change-reasons,omitempty"`
}

func applyResultFromPlan(plan *applyPlan) *ApplyResult {
	result := &ApplyResult{
		AddedNodes:        []string{},
		DeletedNodes:      []string{},
		RecreatedNodes:    []string{},
		StartedNodes:      []string{},
		AddedLinks:        []string{},
		DeletedEndpoints:  []string{},
		RestartedNodes:    []string{},
		NodeChangeReasons: map[string]string{},
	}
	if plan == nil {
		return result
	}

	result.AddedNodes = sortedStringSet(plan.addedNodeSet)
	result.DeletedNodes = sortedStringSet(plan.deletedNodeSet)
	result.RecreatedNodes = sortedStringSet(plan.recreatedNodeSet)
	result.StartedNodes = sortedStringSet(plan.startNodeSet)
	result.AddedLinks = applyLinkNames(plan.addedLinks)
	result.DeletedEndpoints = applyDeletedEndpointNames(plan.staleEndpoints)
	result.RestartedNodes = sortedStringSet(unionStringSets(
		plan.restartNodeSet,
		plan.linkRestartNodeSet,
	))

	for nodeName, reason := range plan.nodeChangeReasons {
		result.NodeChangeReasons[nodeName] = reason
	}

	return result
}

// Apply deploys a lab if it is absent, otherwise it aligns the deployed lab with the
// desired topology using runtime state as baseline.
func (c *CLab) Apply(
	ctx context.Context,
	options *ApplyOptions,
) (*ApplyResult, error) {
	if options == nil {
		var err error
		options, err = NewApplyOptions(0)
		if err != nil {
			return nil, err
		}
	}

	if c.Config.Name == "" {
		return nil, fmt.Errorf("missing lab name")
	}
	if !c.TopoPaths.TopologyFileIsSet() {
		return nil, fmt.Errorf(
			"apply requires a topology file; provide --topo when it cannot be derived from --name",
		)
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return nil, err
	}

	return c.apply(ctx, options, currentNodes)
}

func (c *CLab) apply(
	ctx context.Context,
	options *ApplyOptions,
	currentNodes map[string]*runtimeNodeGroup,
) (*ApplyResult, error) {
	initialDeploy, err := c.needsInitialDeploy(currentNodes)
	if err != nil {
		return nil, err
	}
	if initialDeploy {
		result := &ApplyResult{
			DryRun:      options.dryRun,
			DeployedLab: true,
			LabName:     c.Config.Name,
		}

		if options.dryRun {
			return result, nil
		}

		deployOptions, err := NewDeployOptions(options.maxWorkers)
		if err != nil {
			return nil, err
		}
		deployOptions.SetSkipPostDeploy(options.skipPostDeploy).
			SetSkipLabDirFileACLs(options.skipLabDirFileACLs).
			SetGraph(options.graph).
			SetExportTemplate(options.exportTemplate)

		if _, err := c.deploy(ctx, deployOptions); err != nil {
			return nil, err
		}

		return result, nil
	}

	if err := c.setMgmtBridgeFromRuntime(currentNodes); err != nil {
		return nil, err
	}

	if err := c.resolveMgmtNetLinkNetworks(ctx); err != nil {
		return nil, err
	}

	if err := c.setMgmtNetLinkBridges(); err != nil {
		return nil, err
	}

	if err := c.ResolveLinks(); err != nil {
		return nil, err
	}

	if err := c.checkApplyTopologyDefinition(ctx); err != nil {
		return nil, err
	}

	plan, err := c.planApply(ctx, currentNodes)
	if err != nil {
		return nil, err
	}

	if options.dryRun {
		result := applyResultFromPlan(plan)
		result.DryRun = true
		return result, nil
	}

	if err := c.reconcileNodes(ctx, plan); err != nil {
		return nil, err
	}

	if plan.empty() {
		if c.tailscaleProxyEnabled() {
			if err := c.updateRuntimeInfoForExistingNodes(ctx); err != nil {
				return nil, err
			}
		}
		if err := c.syncTailscaleProxy(ctx); err != nil {
			return nil, err
		}
		if options.finalizeNoop {
			if err := c.prepareApply(
				ctx,
				nil,
				options.skipLabDirFileACLs,
				currentNodes,
			); err != nil {
				return nil, err
			}
		}
		if err := c.SyncMgmtHostRoutes(ctx); err != nil {
			return nil, err
		}
		if options.finalizeNoop {
			if _, err := c.finalize(ctx, options.exportTemplate, options.graph); err != nil {
				return nil, err
			}
		} else {
			c.writeState()
		}
		return applyResultFromPlan(plan), nil
	}

	deployNodeNames := plan.deployNodeNames()
	if err := c.prepareApply(
		ctx,
		deployNodeNames,
		options.skipLabDirFileACLs,
		currentNodes,
	); err != nil {
		return nil, err
	}

	if err := c.deleteApplyEndpoints(ctx, plan.staleEndpoints); err != nil {
		return nil, err
	}

	if err := c.parkRecreatedNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.deleteApplyNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.deployApplyNodes(ctx, plan, options.maxWorkers); err != nil {
		return nil, err
	}

	if err := c.restoreRecreatedNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.removeApplyLinkEndpoints(ctx, plan.addedLinks); err != nil {
		return nil, err
	}

	if err := c.deployLinks(ctx, plan.addedLinks, deployNodeNames); err != nil {
		return nil, err
	}

	if err := c.postDeployApplyNodes(ctx, deployNodeNames, options.skipPostDeploy); err != nil {
		return nil, err
	}

	if err := c.restartApplyNodes(ctx, plan.linkRestartNodeSet); err != nil {
		return nil, err
	}

	if err := c.updateRuntimeInfoForExistingNodes(ctx); err != nil {
		return nil, err
	}
	if err := c.syncTailscaleProxy(ctx); err != nil {
		return nil, err
	}
	if err := c.SyncMgmtHostRoutes(ctx); err != nil {
		return nil, err
	}

	if _, err := c.finalize(ctx, options.exportTemplate, options.graph); err != nil {
		return nil, err
	}

	return applyResultFromPlan(plan), nil
}

func (c *CLab) checkApplyTopologyDefinition(ctx context.Context) error {
	params := *clablinks.NewVerifyLinkParams()
	if len(c.Endpoints) > 0 {
		runtime := c.globalRuntime()
		if runtime == nil {
			return fmt.Errorf("container runtime is not initialized")
		}
		config := runtime.Config()
		if config.VerifyLinkParams != nil {
			params = *config.VerifyLinkParams
		}
	}
	params.AllowExistingEndpoint = true
	if err := c.verifyLinks(ctx, &params); err != nil {
		return err
	}

	if err := c.verifyRootNetNSLinks(); err != nil {
		return err
	}

	for _, nodeName := range sortedNodeNames(c.Nodes) {
		if err := c.Nodes[nodeName].CheckDeploymentConditions(ctx); err != nil {
			return err
		}
	}

	if err := c.verifyDuplicateAddresses(); err != nil {
		return err
	}

	return c.verifyTailscaleProxy()
}

func (c *CLab) prepareApply(
	ctx context.Context,
	addedNodes []string,
	skipLabDirFileACLs bool,
	currentNodes map[string]*runtimeNodeGroup,
) error {
	existing := c.collectExistingManagementAddresses(currentNodes)
	if err := c.prepareLabManagementNetwork(ctx, existing...); err != nil {
		return err
	}

	if err := c.prepareDeployArtifacts(ctx, skipLabDirFileACLs); err != nil {
		return err
	}

	for _, nodeName := range addedNodes {
		if err := c.Nodes[nodeName].PullImage(ctx); err != nil {
			return err
		}
	}

	return nil
}

func (*CLab) removeApplyLinkEndpoints(ctx context.Context, links []clablinks.Link) error {
	for _, link := range links {
		for _, ep := range clablinks.RuntimeEndpoints(link) {
			if err := clablinks.RemoveOwnedInterface(
				ctx,
				ep.GetNode(),
				ep.GetIfaceName(),
			); err != nil {
				return err
			}
		}
	}

	return nil
}

// try to preserve the existing addressing instead of reallocation.
func (c *CLab) collectExistingManagementAddresses(
	currentNodes map[string]*runtimeNodeGroup,
) []clabtypes.ExistingAddress {
	var existing []clabtypes.ExistingAddress
	for name, group := range currentNodes {
		for _, ctr := range group.containers {
			if c.mgmtNetByNetwork(ctr.NetworkName).Network != ctr.NetworkName {
				continue
			}
			for _, value := range []string{ctr.NetworkSettings.IPv4addr, ctr.NetworkSettings.IPv6addr} {
				if ip, err := netip.ParseAddr(value); err == nil {
					existing = append(
						existing,
						clabtypes.ExistingAddress{NodeName: name, ContainerID: ctr.ID, Address: ip},
					)
				}
			}
		}
	}
	return existing
}

